def _schema_has_required_columns(
    conn: sqlite3.Connection,
    required_columns: dict[str, frozenset[str]],
) -> bool:
    """Return whether each required table contains its required columns."""
    for table_name, expected_columns in required_columns.items():
        actual_columns = {
            str(row[1]) for row in conn.execute(f"PRAGMA table_info({table_name})").fetchall()
        }
        if not expected_columns.issubset(actual_columns):
            return False
    return True


def _schema_has_required_primary_keys(
    conn: sqlite3.Connection,
    required_primary_keys: dict[str, tuple[str, ...]],
) -> bool:
    """Return whether each required table has its ordered primary key."""
    for table_name, expected_primary_key in required_primary_keys.items():
        table_rows = conn.execute(f"PRAGMA table_info({table_name})").fetchall()
        actual_primary_key = tuple(
            str(row[1]) for row in sorted(table_rows, key=lambda row: int(row[5])) if row[5]
        )
        if actual_primary_key != expected_primary_key:
            return False
    return True


def _validate_legacy_user_schema(conn: sqlite3.Connection) -> None:
    """Accept an empty database or a recognized unversioned Yinshi database."""
    user_tables = {str(row[0]) for row in conn.execute("""SELECT name FROM sqlite_master
               WHERE type = 'table' AND name NOT LIKE 'sqlite_%'""").fetchall()}
    if user_tables and (
        not _schema_has_required_columns(conn, _LEGACY_USER_SCHEMA_COLUMNS)
        or not _schema_has_required_primary_keys(conn, _LEGACY_USER_SCHEMA_PRIMARY_KEYS)
    ):
        raise RuntimeError("Tenant database legacy schema is not recognized")


def _validate_current_user_schema(conn: sqlite3.Connection) -> None:
    """Reject a migration result that lacks required version-one structure."""
    if not _schema_has_required_columns(
        conn, _CURRENT_USER_SCHEMA_COLUMNS
    ) or not _schema_has_required_primary_keys(conn, _CURRENT_USER_SCHEMA_PRIMARY_KEYS):
        raise RuntimeError("Tenant database current schema is incomplete")


def _ensure_current_user_db_schema(conn: sqlite3.Connection) -> None:
    """Initialize stale schema once while the caller holds the migration lock."""
    version_row = conn.execute("PRAGMA user_version").fetchone()
    if version_row is None or type(version_row[0]) is not int:
        raise RuntimeError("Tenant database schema version is invalid")
    schema_version = version_row[0]
    if schema_version < 0 or schema_version > _USER_SCHEMA_VERSION:
        raise RuntimeError("Tenant database schema version is unsupported")
    if schema_version == _USER_SCHEMA_VERSION:
        return

    _validate_legacy_user_schema(conn)
    journal_row = conn.execute("PRAGMA journal_mode = WAL").fetchone()
    if journal_row is None or str(journal_row[0]).lower() != "wal":
        raise RuntimeError("Tenant database WAL mode could not be enabled")
    conn.execute("BEGIN IMMEDIATE")
    try:
        _ensure_user_db_schema(conn)
        _validate_current_user_schema(conn)
        conn.execute(f"PRAGMA user_version = {_USER_SCHEMA_VERSION}")
        conn.commit()
    except Exception:
        conn.rollback()
        raise


def _load_sqlcipher_module() -> ModuleType:
    """Load an installed SQLCipher DB-API module or raise a clear error."""
    import_errors: list[str] = []
    for module_name in _SQLCIPHER_MODULE_NAMES:
        try:
            module = importlib.import_module(module_name)
        except ImportError as exc:
            import_errors.append(f"{module_name}: {exc}")
            continue
        if not hasattr(module, "connect"):
            import_errors.append(f"{module_name}: missing connect")
            continue
        if not hasattr(module, "Row"):
            import_errors.append(f"{module_name}: missing Row")
            continue
        return module
    joined_errors = "; ".join(import_errors) or "no SQLCipher module candidates configured"
    raise RuntimeError(
        "TENANT_DB_ENCRYPTION requires sqlcipher3 or pysqlcipher3. "
        f"Import failures: {joined_errors}"
    )


def _tenant_database_key(tenant: TenantContext) -> bytes:
    """Derive the SQLCipher key for one tenant database from the user's DEK."""
    if tenant is None:
        raise ValueError("tenant is required when tenant DB encryption is enabled")
    from yinshi.services.keys import get_user_dek

    user_dek = get_user_dek(tenant.user_id)
    return derive_subkey(user_dek, purpose="tenant-sqlcipher", context=tenant.user_id)


def _open_sqlcipher_connection(db_path: str, sqlcipher_key: bytes) -> sqlite3.Connection:
    """Open a SQLCipher-backed SQLite connection and validate the key immediately."""
    if not isinstance(db_path, str):
        raise TypeError("db_path must be a string")
    if not db_path.strip():
        raise ValueError("db_path must not be empty")
    if not isinstance(sqlcipher_key, bytes):
        raise TypeError("sqlcipher_key must be bytes")
    if len(sqlcipher_key) != 32:
        raise ValueError("sqlcipher_key must be exactly 32 bytes")

    Path(db_path).parent.mkdir(parents=True, exist_ok=True)
    sqlcipher_module = _load_sqlcipher_module()
    sqlcipher_database_error = getattr(
        sqlcipher_module,
        "DatabaseError",
        sqlite3.DatabaseError,
    )
    if not isinstance(sqlcipher_database_error, type) or not issubclass(
        sqlcipher_database_error,
        Exception,
    ):
        sqlcipher_database_error = sqlite3.DatabaseError
    sqlcipher_operational_error = getattr(
        sqlcipher_module,
        "OperationalError",
        sqlite3.OperationalError,
    )
    if not isinstance(sqlcipher_operational_error, type) or not issubclass(
        sqlcipher_operational_error,
        Exception,
    ):
        sqlcipher_operational_error = sqlite3.OperationalError

    for attempt in range(_SQLCIPHER_OPEN_ATTEMPTS):
        conn: sqlite3.Connection | None = None
        try:
            conn = cast(sqlite3.Connection, sqlcipher_module.connect(db_path))
            conn.row_factory = getattr(sqlcipher_module, "Row")
            # The key is derived binary material, converted to hex locally, and never
            # includes user-controlled SQL. SQLCipher requires PRAGMA key syntax.
            conn.execute(f"PRAGMA key = \"x'{sqlcipher_key.hex()}'\"")  # noqa: S608
            conn.execute("PRAGMA foreign_keys = ON")
            conn.execute("PRAGMA busy_timeout = 5000")
            conn.execute("SELECT count(*) FROM sqlite_master").fetchone()
            return conn
        except (sqlite3.DatabaseError, sqlcipher_database_error) as exc:
            if conn is not None:
                conn.close()
            is_transient = isinstance(exc, sqlcipher_operational_error) and (
                str(exc) in _SQLCIPHER_TRANSIENT_OPEN_ERRORS
            )
            if not is_transient or attempt + 1 >= _SQLCIPHER_OPEN_ATTEMPTS:
                raise RuntimeError(
                    "Tenant database could not be opened with the configured key"
                ) from exc
            time.sleep(_SQLCIPHER_OPEN_RETRY_DELAY_SECONDS * (attempt + 1))

    raise AssertionError("SQLCipher connection attempts must return or raise")


def _plaintext_database_readable(db_path: str) -> bool:
    """Return whether a database can be opened by plaintext stdlib SQLite."""
    if not os.path.exists(db_path):
        return False
    try:
        conn = _open_connection(db_path)
        try:
            conn.execute("SELECT count(*) FROM sqlite_master").fetchone()
            return True
        finally:
            conn.close()
    except sqlite3.DatabaseError:
        return False


