def get_github_clone_access_resolver(
    request: Request,
) -> GitHubCloneAccessResolver | None:
    """Return the configured runtime GitHub clone access resolver."""
    resolver = getattr(request.app.state, "github_clone_access_resolver", None)
    if resolver is None:
